function drawStadium(){
  const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#07111d');sky.addColorStop(.52,'#102637');sky.addColorStop(1,'#08131d');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
  // Floodlit stands, a broadcast ribbon and a dense crowd silhouette frame the pitch.
  for(let row=0;row<5;row++){const y=9+row*11;ctx.fillStyle=row%2?'#152b3b':'#1a3445';ctx.fillRect(0,y,W,8);ctx.fillStyle='#b8e4ef12';ctx.fillRect(0,y+7,W,1);}
  for(let i=0;i<190;i++){const x=(i*67)%W,y=14+((i*29)%45);ctx.fillStyle=['#86cce0','#f4bd62','#e77973','#d7ecf0'][i%4];ctx.globalAlpha=.12+(i%5)*.035;ctx.fillRect(x,y,2,2)}ctx.globalAlpha=1;
  const ribbon=ctx.createLinearGradient(0,470,0,520);ribbon.addColorStop(0,'#102b3b');ribbon.addColorStop(1,'#07121d');ctx.fillStyle=ribbon;ctx.fillRect(0,465,W,95);ctx.fillStyle='#36dce9';ctx.fillRect(0,466,W,2);ctx.fillStyle='#c9f8ff';ctx.font='800 10px "Barlow Condensed"';ctx.letterSpacing='3px';ctx.textAlign='center';ctx.fillText('BLUE LOCK ARENA  /  THE FIRST SELECTION',W/2,491);ctx.letterSpacing='0px';
  for(let i=0;i<5;i++){const x=70+i*215;ctx.fillStyle='#e7fcff';ctx.globalAlpha=.2;ctx.beginPath();ctx.ellipse(x,38,27,5,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=.65;ctx.fillStyle='#e6fbff';ctx.fillRect(x-1,12,2,24)}ctx.globalAlpha=1;
}
function draw(){ctx.clearRect(0,0,W,H);drawStadium();ctx.save();ctx.transform(.94,0,.07,.70,25,60);drawField();drawTactic();const all=[...state.teammates,...state.enemies,state.player].sort((a,b)=>a.y-b.y);all.forEach(u=>drawPlayer(u,u===state.player));drawBall();ctx.restore();drawMini();requestAnimationFrame(draw)}

