node --input-type=module <<'NODE'
import { spawn } from 'node:child_process';
import { writeFile } from 'node:fs/promises';
const port = 9223;
const chrome = spawn('chromium', ['--headless', '--no-sandbox', '--disable-gpu', '--hide-scrollbars', `--remote-debugging-port=${port}`, '--window-size=1280,900', 'about:blank'], { stdio: 'ignore' });
try {
  let targets;
  for (let i = 0; i < 50; i++) {
    try { targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json(); break; } catch { await new Promise(r => setTimeout(r, 100)); }
  }
  const page = targets?.find(x => x.type === 'page');
  if (!page) throw new Error('Chromium debugging page unavailable');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
  let id = 0;
  const pending = new Map();
  ws.onmessage = ({ data }) => { const msg = JSON.parse(data); if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); } };
  const call = (method, params = {}) => new Promise(resolve => { const n = ++id; pending.set(n, resolve); ws.send(JSON.stringify({ id: n, method, params })); });
  await call('Page.enable');
  await call('Emulation.setDeviceMetricsOverride', { width: 1280, height: 900, deviceScaleFactor: 1, mobile: false });
  await call('Page.navigate', { url: 'http://127.0.0.1:8765/' });
  await new Promise(r => setTimeout(r, 3000));
  const result = await call('Page.captureScreenshot', { format: 'jpeg', quality: 78, fromSurface: true });
  if (!result.result?.data) throw new Error('JPEG capture returned no image data');
  const path = '/tmp/opencode/blue-lock-latest.jpg';
  await writeFile(path, Buffer.from(result.result.data, 'base64'));
  console.log(path, (await import('node:fs')).statSync(path).size, 'bytes');
  ws.close();
} finally { chrome.kill(); }
